class Component extends DCLogic {
  componentDidMount(){ const go=()=>window.SWD?SWD.ready(()=>this.init()):setTimeout(go,30); go(); }
  init(){
    const D=SW_DEMO_DATA, CF=SW_DEMO, $=id=>document.getElementById(id), UF=SWD.UFS(), CT=CF.country;
    SWD.page({active:'geral',lv:'BR',label:'Visão geral'});
    const M={
      pop:{n:'População',sm:'População',t:'População por estado',s:'Pessoas contadas no Censo 2022.',v:D.pop,src:'pop',col:'Pessoas',fmt:v=>SWD.mi(v,true),cuts:[1e6,3e6,5e6,1e7,2e7],legend:['até 1 mi','1–3 mi','3–5 mi','5–10 mi','10–20 mi','20 mi ou mais'],big:v=>SWD.mi(v)},
      dens:{n:'Densidade',sm:'Densidade',t:'Densidade, pessoas por km²',s:'População do Censo 2022 dividida pela área do estado.',v:D.dens,src:'dens',col:'hab/km²',fmt:v=>SWD.num(v,1),cuts:[5,10,25,50,100],legend:['até 5','5–10','10–25','25–50','50–100','100 ou mais'],big:v=>SWD.num(v,1)+'<small>hab/km²</small>'},
      cresc:{n:'Crescimento 2010–2022',sm:'Crescimento',t:'Crescimento entre os Censos 2010 e 2022',s:'Taxa média de crescimento ao ano.',v:D.tx,src:'pop',col:'% ao ano',fmt:v=>SWD.sgn(v,2,'%'),div:true,big:v=>SWD.sgn(v,2)+'<small>% ao ano</small>'},
      idmed:{n:'Idade mediana',sm:'Idade',t:'Idade mediana',s:'Metade das pessoas tem menos que esta idade. Calculada sobre as faixas de 5 anos do Censo 2022.',v:D.idmed,src:'pyr',col:'Anos',fmt:v=>SWD.num(v,1),cuts:[27,30,32,34,36],legend:['até 27 anos','27–30','30–32','32–34','34–36','36 ou mais'],big:v=>SWD.num(v,1)+'<small>anos</small>'}
    };
    const st={m:SWD.q.get('m')||'pop',sel:'BR',hov:null,c:'idade'};
    const map=new SW.Map($('map'),{aria:'Mapa dos estados',onHover:u=>{st.hov=u;draw()},onClick:u=>{st.sel=st.sel===u?'BR':u;draw();bottom()}});
    const rank=new SW2.Ranking($('rank'),{onHover:u=>{st.hov=u;draw()},onClick:u=>{st.sel=u;draw();bottom()}});
    SWD.seg($('meas'),Object.entries(M).map(([k,m])=>[k,m.n,m.sm]),st.m,k=>{st.m=k;paint();draw()},'Medida do mapa');
    const paint=()=>{ const m=M[st.m];
      $('vt').textContent=m.t; $('vs').textContent=m.s; $('vstamp').innerHTML=SWD.stamp(m.src);
      map.update({fill:u=>{const x=m.v[u]; if(x==null) return {hatch:true}; const k=SWD.cls(x,m.div?SWD.GROW.cuts:m.cuts); return {f:`var(--${m.div?'d':'r'}${k})`,k:m.div?(k===0||k===5?4:0):k}}});
      $('legend').innerHTML=m.div?SWD.divLegend():SWD.legend(m.legend,'r',UF.filter(u=>m.v[u]==null).length,'estados');
      $('src').innerHTML=SWD.srcLine([m.src]); };
    const draw=()=>{ const m=M[st.m], show=st.hov||st.sel, x=m.v[show], rr=SW2.rankOf(Object.fromEntries(UF.map(u=>[u,m.v[u]])),show), uf=show!=='BR';
      map.mark(st.sel==='BR'?null:st.sel,st.hov);
      const sub=CF.sub[show], fact=(l,v)=>`<div class="fact"><span>${l}</span><b>${v}</b></div>`;
      $('card').innerHTML=`<div class="card" aria-live="polite">
        <div class="meta">${uf?`${SWD.region(show)} · ${rr.rank?`${rr.rank}º de ${rr.of} em ${m.n.toLowerCase()}`:'sem dado'}`:`${UF.length} ${CT.units}`}</div>
        <div class="row1"><div class="nm">${SWD.name(show)}</div>${x==null?SWD.nodata():`<div class="big">${m.big(x)}</div>`}</div>
        <div style="margin-top:2px">${SWD.stamp(m.src)}</div>
        <div style="margin-top:16px;padding-top:14px;border-top:1px solid var(--line)" id="live"></div>
        <div class="facts">${fact('Censo 2022',SWD.int(D.pop[show])+' pessoas')}${fact('Densidade',SWD.num(D.dens[show],1)+' hab/km²')}${fact('Crescimento 2010–2022',SWD.sgn(D.tx[show],2,'% ao ano'))}${fact('Idade mediana',SWD.num(D.idmed[show],1)+' anos')}${fact('Pessoas por domicílio',SWD.num(D.dom[show][1],2))}</div>
        <div class="line" style="font-size:14px;justify-content:space-between;flex-wrap:wrap">${uf?(sub?`<a href="${SWD.href('SUB','geral')}">Ver ${sub.name} por município →</a>`:`<span style="color:var(--sub)">Por município</span><span class="soon">em breve</span>`):'<span style="color:var(--sub)">Escolha um estado no mapa ou na lista.</span>'}${uf&&st.sel!=='BR'?`<button type="button" id="back" style="border:0;background:none;color:var(--accent);cursor:pointer;padding:0;font-size:14px">Voltar a ${CT.name}</button>`:''}</div></div>`;
      if(!this.liveFor||this.liveFor!==show||!document.querySelector('#live .n')) { this.liveFor=show; }
      SWD.live($('live'),show);
      const b=$('back'); if(b) b.onclick=()=>{st.sel='BR';draw();bottom()};
      rank.render({rows:UF.map(u=>({uf:u,v:m.v[u],txt:m.v[u]==null?'sem dado':m.fmt(m.v[u])})),sel:st.sel,hov:st.hov,col:m.col,head:'Estado',plural:'estados'});
    };
    const C100={idade:['Idade','pyr'],raca:['Cor ou raça','raca'],sit:['Onde moram','sit']};
    SWD.seg($('c100seg'),Object.entries(C100).map(([k,v])=>[k,v[0]]),st.c,k=>{st.c=k;bottom()},'Cada 100 pessoas por');
    const bottom=()=>{ const l=st.sel, P=D.pyr[l], s=SWD.ageStats(P);
      $('c100s').textContent=`Em ${SWD.name(l)}, no Censo 2022.`; $('c100stamp').innerHTML=SWD.stamp(C100[st.c][1]);
      let cats;
      if(st.c==='idade'){ const t=P[0].map((m,i)=>m+P[1][i]), sum=(a,b)=>t.slice(a,b).reduce((x,y)=>x+y,0); cats=[{k:'a',n:'0 a 14 anos',v:sum(0,3),c:'var(--r1)'},{k:'b',n:'15 a 64 anos',v:sum(3,13),c:'var(--r3)'},{k:'c',n:'65 anos ou mais',v:sum(13,17),c:'var(--r5)'}]; }
      else if(st.c==='raca') cats=CF.RACA.map((r,i)=>({k:r.k,n:r.n,v:D.raca[l][i],c:`var(--c${i+1})`}));
      else cats=[{k:'u',n:'Área urbana',v:D.sit[l][0],c:'var(--r4)'},{k:'r',n:'Área rural',v:D.sit[l][1],c:'var(--c2)'}];
      SWD.cada100($('c100'),cats,{title:SWD.name(l),aria:`Cada 100 pessoas em ${SWD.name(l)}`});
      if(st.c==='raca') $('c100').insertAdjacentHTML('beforeend',SW2.note('Termos e categorias do IBGE. As cores do gráfico só distinguem as categorias.'));
      SWD.pyramid($('mpyr'),{a:P,cmp:l==='BR'?null:D.pyr.BR,cmpLabel:CT.name,W:460,H:360,max:5,aria:`Pirâmide etária de ${SWD.name(l)}, 2022`});
      $('mpyrst').innerHTML=`<div class="lgx"><span><i style="background:var(--sx-m)"></i>Homens</span><span><i style="background:var(--sx-f)"></i>Mulheres</span>${l==='BR'?'':`<span><i class="ln"></i>${CT.name}</span>`}<span>Idade mediana ${SWD.num(s.med,1)} anos</span></div><div style="margin-top:8px">${SWD.stamp('pyr')}</div>`;
      $('pyrlink').href=SWD.href('BR','idade',l==='BR'?'':'u='+l);
    };
    paint(); draw(); bottom();
  }
  renderVals(){ return {}; }
}
